-- Postgres dialect of schema/0963_github_webhook.sql (issue #771, AC-10 follow-up; kept in parity with the SQLite file by
-- TestSchemaParity_SQLiteAndPostgres). Neither table references another tenant table, so no composite foreign key is
-- needed. rls.sql is regenerated by `tessera admin gen-rls`.

-- +goose Up

CREATE TABLE github_webhook_secrets (
  tenant_id TEXT NOT NULL PRIMARY KEY REFERENCES tenants (id),
  secret_enc BYTEA NOT NULL,
  set_at TEXT NOT NULL,
  set_by TEXT NOT NULL
);

CREATE TABLE github_webhook_deliveries (
  tenant_id TEXT NOT NULL REFERENCES tenants (id),
  delivery_id TEXT NOT NULL CHECK (length(delivery_id) BETWEEN 1 AND 100),
  expires_at TEXT NOT NULL,
  PRIMARY KEY (tenant_id, delivery_id)
);
CREATE INDEX ix_github_webhook_deliveries_expiry ON github_webhook_deliveries (tenant_id, expires_at);
